-- Opsional: dijalankan otomatis oleh aplikasi. Bisa juga ditempel manual di Supabase SQL Editor.
CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT NOT NULL, pass TEXT NOT NULL, role TEXT NOT NULL, created BIGINT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS users_username_ci ON users(lower(username));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS links(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, descr TEXT DEFAULT '', type TEXT NOT NULL, access TEXT NOT NULL DEFAULT 'all', url TEXT, file_name TEXT, file_key TEXT, size INTEGER DEFAULT 0, downloads INTEGER DEFAULT 0, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS reqs(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, link_id INTEGER NOT NULL REFERENCES links(id) ON DELETE CASCADE, platform TEXT NOT NULL, label TEXT DEFAULT '', url TEXT NOT NULL, target_id TEXT DEFAULT '', sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS verifs(viewer TEXT NOT NULL, req_id INTEGER NOT NULL REFERENCES reqs(id) ON DELETE CASCADE, method TEXT NOT NULL, ts BIGINT NOT NULL, PRIMARY KEY(viewer, req_id));
CREATE TABLE IF NOT EXISTS starts(viewer TEXT NOT NULL, req_id INTEGER NOT NULL REFERENCES reqs(id) ON DELETE CASCADE, ts BIGINT NOT NULL, PRIMARY KEY(viewer, req_id));
CREATE TABLE IF NOT EXISTS announcements(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, link_id INTEGER REFERENCES links(id) ON DELETE SET NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS login_fail(ip TEXT NOT NULL, ts BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS login_fail_ip ON login_fail(ip, ts);
